  "inlineSchema": "// Prisma schema for the credential verification platform\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// User management\nmodel User {\n  id         String   @id @default(cuid())\n  wallet     String   @unique\n  did        String   @unique\n  name       String?\n  bio        String?\n  avatarUrl  String?\n  links      Json? // Social links array\n  isVerified Boolean  @default(false)\n  reputation Int      @default(0)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  credentials      Credential[]\n  verificationLogs VerificationLog[]\n  sessions         UserSession[]\n\n  @@map(\"users\")\n}\n\n// Credential storage with W3C VC compliance\nmodel Credential {\n  id             String           @id @default(cuid())\n  userId         String\n  vcId           String           @unique // W3C VC ID\n  skill          String\n  organization   String\n  issuer         String\n  issuanceDate   DateTime\n  expirationDate DateTime?\n  proof          Json // W3C VC proof object\n  status         CredentialStatus @default(VALID)\n  metadata       Json? // Additional issuer-specific data\n  revokedReason  String?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  user             User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  verificationLogs VerificationLog[]\n\n  @@map(\"credentials\")\n}\n\n// Audit trail for verification attempts\nmodel VerificationLog {\n  id           String             @id @default(cuid())\n  userId       String\n  credentialId String?\n  source       String // GitHub, Coursera, AWS, etc.\n  skill        String\n  result       Json // Detailed verification response\n  status       VerificationStatus\n  timestamp    DateTime           @default(now())\n\n  user       User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  credential Credential? @relation(fields: [credentialId], references: [id], onDelete: SetNull)\n\n  @@map(\"verification_logs\")\n}\n\n// Session management\nmodel UserSession {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"user_sessions\")\n}\n\n// Issuer schema definitions\nmodel IssuerSchema {\n  id             String   @id @default(cuid())\n  issuerName     String   @unique\n  requiredFields Json // Schema definition\n  isActive       Boolean  @default(true)\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@map(\"issuer_schemas\")\n}\n\n// File uploads for evidence\nmodel FileUpload {\n  id         String   @id @default(cuid())\n  userId     String\n  fileName   String\n  filePath   String\n  fileSize   Int\n  mimeType   String\n  uploadedAt DateTime @default(now())\n\n  @@map(\"file_uploads\")\n}\n\n// Analytics and metrics\nmodel Analytics {\n  id        String   @id @default(cuid())\n  metric    String\n  value     Float\n  metadata  Json?\n  timestamp DateTime @default(now())\n\n  @@map(\"analytics\")\n}\n\nenum CredentialStatus {\n  VALID\n  EXPIRED\n  REVOKED\n  PENDING\n}\n\nenum VerificationStatus {\n  SUCCESS\n  FAILED\n  PENDING\n  ERROR\n}\n",
